extractor:
function extract(raw, memory, info) {
  var KNOWN = { playing: 1, head: 1, body: 1, coin: 1, heading: 1, turn: 1, edge: 1, score: 1, headOnScreen: 1, screen: 1 };
  var GOOD = /coin|food|apple|fruit|pellet|pickup|bonus|gem|reward/i;
  var DECOR = /cloud|star|decor|particle|score|text|label|background|hud|camera|offset|scale|angle|rotation|velocity|speed|direction|heading|turn|screen|best|time/i;
  function isCell(v) { return Array.isArray(v) && v.length >= 2 && typeof v[0] === 'number' && typeof v[1] === 'number'; }
  function cellsOf(v, depth, out) {
    if (isCell(v)) out.push([Math.round(v[0]), Math.round(v[1])]);
    else if (v && typeof v === 'object' && !Array.isArray(v) && typeof v.x === 'number' && typeof v.y === 'number') out.push([Math.round(v.x), Math.round(v.y)]);
    else if (Array.isArray(v) && depth < 2) { for (var j = 0; j < v.length; j++) cellsOf(v[j], depth + 1, out); }
    return out;
  }
  if (!raw || !raw.playing || !isCell(raw.head)) {
    memory.wait = (memory.wait || 0) + 1;
    return { playing: false, screen: String((raw && raw.screen) || 'End'), waitPhase: (memory.wait - 1) % 4 };
  }
  memory.wait = 0;
  var E = typeof raw.edge === 'number' && raw.edge > 0 ? Math.round(raw.edge) : 8;
  var N = 2 * E + 1, NN = N * N, i;
  function inB(x, y) { return x >= -E && x <= E && y >= -E && y <= E; }
  function idx(x, y) { return (x + E) + (y + E) * N; }
  var hx = Math.round(raw.head[0]), hy = Math.round(raw.head[1]);
  var body = cellsOf(raw.body, 0, []);
  var coins = cellsOf(raw.coin, 0, []);
  var blocked = [];
  for (i = 0; i < NN; i++) blocked.push(false);
  var unkCount = 0, unkKind = '', unkDx = 0, unkDy = 0, unkBest = 1e9;
  for (var key in raw) {
    if (KNOWN[key] || DECOR.test(key)) continue;
    var cs = cellsOf(raw[key], 0, []);
    if (!cs.length) continue;
    if (GOOD.test(key)) { coins = coins.concat(cs); continue; }
    for (i = 0; i < cs.length; i++) {
      var ux = cs[i][0], uy = cs[i][1];
      if (inB(ux, uy)) blocked[idx(ux, uy)] = true;
      unkCount++;
      var ud = Math.abs(ux - hx) + Math.abs(uy - hy);
      if (ud < unkBest) { unkBest = ud; unkKind = key; unkDx = ux - hx; unkDy = uy - hy; }
    }
  }
  var headIn = inB(hx, hy);
  var snake = [headIn ? idx(hx, hy) : -1], occ = {};
  for (i = 0; i < body.length; i++) {
    var bc = inB(body[i][0], body[i][1]) ? idx(body[i][0], body[i][1]) : -1;
    snake.push(bc);
    if (bc >= 0) occ[bc] = true;
  }
  var L = snake.length;
  var coinCells = [], isCoin = {};
  for (i = 0; i < coins.length; i++) {
    if (!inB(coins[i][0], coins[i][1])) continue;
    var ci = idx(coins[i][0], coins[i][1]);
    if (isCoin[ci] || occ[ci] || ci === snake[0]) continue;
    isCoin[ci] = true;
    coinCells.push(ci);
  }
  var OPP = { up: 'down', down: 'up', left: 'right', right: 'left' };
  var heading = OPP[raw.heading] ? raw.heading : null;
  if (!heading && body.length) {
    var hdx = hx - body[0][0], hdy = hy - body[0][1];
    heading = hdx > 0 ? 'right' : hdx < 0 ? 'left' : hdy > 0 ? 'down' : 'up';
  }
  if (!heading) heading = 'up';
  var turn = OPP[raw.turn] && raw.turn !== OPP[heading] ? raw.turn : heading;
  var NAMES = ['up', 'down', 'left', 'right'], DX = [0, 0, -1, 1], DY = [-1, 1, 0, 0];
  function reach(sn) {
    var n = sn.length, need = [], dist = [], c;
    for (c = 0; c < NN; c++) { need.push(0); dist.push(-1); }
    for (c = 1; c < n; c++) if (sn[c] >= 0 && need[sn[c]] < n - c + 1) need[sn[c]] = n - c + 1;
    var q = [sn[0]], qh = 0, tail = false;
    dist[sn[0]] = 0;
    while (qh < q.length) {
      var cur = q[qh++], t = dist[cur] + 1, cx = cur % N, cy = (cur - cx) / N;
      for (var k = 0; k < 4; k++) {
        var ax = cx + DX[k], ay = cy + DY[k];
        if (ax < 0 || ay < 0 || ax >= N || ay >= N) continue;
        var ni = ax + ay * N;
        if (dist[ni] >= 0 || blocked[ni] || need[ni] > t) continue;
        dist[ni] = t;
        q.push(ni);
        if (need[ni] > 0) tail = true;
      }
    }
    return { dist: dist, order: q, tail: tail };
  }
  function nextCost(sn) {
    var r = reach(sn), mine = {}, sum = 0, cnt = 0, c;
    for (c = 0; c < sn.length; c++) if (sn[c] >= 0) mine[sn[c]] = true;
    for (c = 0; c < NN; c++) {
      if (mine[c] || blocked[c]) continue;
      cnt++;
      sum += r.dist[c] >= 0 ? r.dist[c] : 60;
    }
    var escape = r.tail || r.order.length - 1 >= 2 * sn.length;
    return (cnt ? sum / cnt : 0) + (escape ? 0 : 300);
  }
  function planPath(r, start, target, firstDir, preferTurn) {
    var dist = r.dist, on = {}, o, k, p, px, py, ax, ay, ni;
    on[target] = true;
    for (o = r.order.length - 1; o >= 0; o--) {
      p = r.order[o];
      if (on[p] || dist[p] >= dist[target]) continue;
      px = p % N; py = (p - px) / N;
      for (k = 0; k < 4; k++) {
        ax = px + DX[k]; ay = py + DY[k];
        if (ax < 0 || ay < 0 || ax >= N || ay >= N) continue;
        ni = ax + ay * N;
        if (on[ni] && dist[ni] === dist[p] + 1) { on[p] = true; break; }
      }
    }
    var path = [start], cur = start, hd = firstDir;
    while (cur !== target && path.length <= NN) {
      var cx = cur % N, cy = (cur - cx) / N, pick = -1, pickD = -1;
      for (k = 0; k < 4; k++) {
        ax = cx + DX[k]; ay = cy + DY[k];
        if (ax < 0 || ay < 0 || ax >= N || ay >= N) continue;
        ni = ax + ay * N;
        if (!on[ni] || dist[ni] !== dist[cur] + 1) continue;
        if (pick < 0 || (preferTurn ? (pickD === hd && k !== hd) : k === hd)) { pick = ni; pickD = k; }
      }
      if (pick < 0) break;
      path.push(pick);
      cur = pick;
      hd = pickD;
    }
    return cur === target ? path : null;
  }
  var state = { playing: true, heading: heading, turn: turn };
  for (var d = 0; d < 4; d++) {
    var name = NAMES[d], nx = hx + DX[d], ny = hy + DY[d];
    var ok = headIn && inB(nx, ny) && name !== OPP[heading] && !occ[idx(nx, ny)] && !blocked[idx(nx, ny)];
    var room = 0, safe = false, steps = 99, total = 499;
    if (ok) {
      var start = idx(nx, ny), eats = !!isCoin[start];
      var snake1 = [start].concat(eats ? snake : snake.slice(0, L - 1));
      var r = reach(snake1);
      room = r.order.length - 1;
      safe = r.tail || room >= 2 * L;
      if (eats) { steps = 0; total = nextCost(snake1); }
      else if (!coinCells.length) total = nextCost(snake1);
      else {
        var target = -1;
        for (i = 0; i < coinCells.length; i++) {
          var cc = coinCells[i];
          if (r.dist[cc] > 0 && (target < 0 || r.dist[cc] < r.dist[target])) target = cc;
        }
        total = 250;
        if (target >= 0) {
          steps = Math.min(r.dist[target], 98);
          var bestNext = 1e9;
          for (var v = 0; v < 2; v++) {
            var path = planPath(r, start, target, d, v === 1);
            if (!path) continue;
            var nc = nextCost(path.slice().reverse().concat(snake).slice(0, L + 1));
            if (nc < bestNext) bestNext = nc;
          }
          total = steps + (bestNext < 1e9 ? bestNext : 60);
        }
      }
    }
    state[name + 'Ok'] = ok;
    state[name + 'Safe'] = ok && safe;
    state[name + 'Coin'] = steps;
    state[name + 'Total'] = Math.min(Math.round(total), 499);
    state[name + 'Room'] = room;
  }
  if (unkCount) { state.unknownKind = unkKind; state.unknownCount = unkCount; state.unknownDx = unkDx; state.unknownDy = unkDy; }
  return state;
}

teacher:
function teach(state) {
  var s = state;
  if (!s.playing) {
    var w = s.waitPhase || 0;
    return w === 1 ? 'key_up' : (w === 3 ? 'start' : 'wait');
  }
  var dirs = ['up', 'down', 'left', 'right'], cand = [], i;
  for (i = 0; i < 4; i++) if (s[dirs[i] + 'Safe']) cand.push(dirs[i]);
  var safeMode = cand.length > 0;
  if (!safeMode) for (i = 0; i < 4; i++) if (s[dirs[i] + 'Ok']) cand.push(dirs[i]);
  var turn = s.turn || s.heading || 'up';
  if (!cand.length) return 'key_' + turn;
  function cmp(a, b) {
    if (!safeMode && s[a + 'Room'] !== s[b + 'Room']) return s[b + 'Room'] - s[a + 'Room'];
    return s[a + 'Total'] - s[b + 'Total'];
  }
  var best = [cand[0]];
  for (i = 1; i < cand.length; i++) {
    var c = cmp(cand[i], best[0]);
    if (c < 0) best = [cand[i]];
    else if (c === 0) best.push(cand[i]);
  }
  if (best.length === 1) return 'key_' + best[0];
  for (i = 0; i < best.length; i++) if (best[i] === turn) return 'key_' + turn;
  var out = {};
  for (i = 0; i < best.length; i++) out['key_' + best[i]] = 1 / best.length;
  return out;
}
